#include <stdio.h>

/* 计算 ceil(log_k(m))：反复除以 k 直到为 1 */
int ceil_log_k(int m, int k) {
    int t = 0;
    int cur = 1;
    while (cur < m) { cur *= k; t++; }
    return t;
}

int main(void) {
    int N = 100000;     /* 总记录数 */
    int M = 1000;       /* 内存可容纳记录数 */
    int m = (N + M - 1) / M;   /* 初始顺串数 = ceil(N/M) */

    printf("外部排序参数: N=%d 个记录, 内存 M=%d, 顺串数 m=ceil(N/M)=%d\n\n", N, M, m);
    printf("%-8s %-12s %-16s %-14s\n", "路数 k", "归并趟数", "总 I/O(记录数)", "需比较次数/记录");
    printf("--------------------------------------------------------------------\n");

    int ks[] = {2, 4, 8, 16};
    for (int idx = 0; idx < 4; idx++) {
        int k = ks[idx];
        int passes = ceil_log_k(m, k);
        long io = 2L * N * passes;                 /* 每趟读一遍 + 写一遍 */
        printf("%-8d %-12d %-16ld %-14d\n", k, passes, io, k - 1);
    }

    printf("\n规律: 趟数 = ceil(log_k m)，k 增大趟数对数下降，I/O = 2*N*趟数 同步下降\n");
    printf("代价1: 需要 k 个输入缓冲区 -> 内存 O(k)\n");
    printf("代价2: k 路选最小需 k-1 次比较 -> 必须用败者树降到 ceil(log2 k) 次\n");

    long io2 = 2L * N * ceil_log_k(m, 2);
    long io8 = 2L * N * ceil_log_k(m, 8);
    printf("\nk=2 -> k=8: I/O 从 %ld 降到 %ld，下降 %.0f%%\n",
           io2, io8, 100.0 * (io2 - io8) / io2);

    printf("\n优化3: 置换-选择可使初始顺串平均长度达 2M=%d，顺串数减半 -> 趟数再降\n", 2 * M);
    int m2 = (N + 2 * M - 1) / (2 * M);
    printf("  置换-选择后 m=%d，k=8 时趟数 = %d（原 %d）\n", m2, ceil_log_k(m2, 8), ceil_log_k(m, 8));
    printf("优化4: 顺串长度不等时按哈夫曼思想构造最佳归并树；(m-1) mod (k-1) != 0 需补虚段\n");
    return 0;
}
